id1 = PermutationGroup.id(1)
id2 = PermutationGroup.id(2)
id3 = PermutationGroup.id(3)
id4 = PermutationGroup.id(4)
id5 = PermutationGroup.id(5)
swap2 = _ia([1, 0])
trans3 = _ia([1, 0, 2])
